struct Handle {HANDLE value=nullptr;~Handle(){if(value)CloseHandle(value);}Handle()=default;Handle(const Handle&)=delete;};
FrameKey Key(const CapturedFrame& f,uint64_t source){return {source,f.stamp.streamEpoch,f.stamp.sequence,f.stamp.geometryEpoch,f.stamp.configEpoch};}
bool SameEpochs(const FrameKey& a,const FrameKey& b){return a.sourceId==b.sourceId&&a.streamEpoch==b.streamEpoch&&a.geometryEpoch==b.geometryEpoch&&a.configEpoch==b.configEpoch;}
