Dav2Host::Dav2Host():impl_(std::make_unique<Impl>()){}
Dav2Host::~Dav2Host(){Stop();if(impl_->quarantined)impl_.release();}
bool Dav2Host::Initialize(ID3D11Device* device,ID3D11DeviceContext* context,const Settings& settings,const std::filesystem::path& root,std::string& reason){Stop();if(impl_->quarantined){reason="Depth generation retained; restart worker required";return false;}impl_=std::make_unique<Impl>();auto& p=*impl_;p.settings=settings;try{if(!ValidSettings(settings)||settings.provider!=Provider::Dav2||!device||!context)throw std::runtime_error("Depth settings/device unavailable");LARGE_INTEGER f{};QueryPerformanceFrequency(&f);p.frequency=double(f.QuadPart);p.Setup(device,context,root);reason=p.reason;return true;}catch(const std::exception& e){p.reason=reason=e.what();return false;}}
void Dav2Host::Offer(const CapturedFrame& frame,uint64_t sourceId){auto& p=*impl_;if(!p.ready||p.stopping||p.quarantined||!frame.texture)return;const auto key=Key(frame,sourceId);p.latest=key;if(p.jobs.Offer(key))p.pending=frame;}
void Dav2Host::ObserveEpochs(const FrameKey& key){auto& p=*impl_;if(!SameEpochs(p.latest,key)){p.latest=key;p.pending.reset();p.jobs.DiscardPending();}}
std::optional<DepthFrame> Dav2Host::Poll(std::string& reason){auto& p=*impl_;try{auto r=p.Poll();reason=p.reason;return r;}catch(const std::exception& e){if(p.phase==Impl::Phase::Idle&&!p.quarantined){p.ready=false;if(p.jobs.Active())p.jobs.Finish(*p.jobs.Active());p.active.reset();p.pending.reset();}else p.quarantined=true;p.reason=reason=e.what();return {};}}
void Dav2Host::Stop(){auto& p=*impl_;p.stopping=true;p.jobs.Invalidate();p.pending.reset();const auto start=GetTickCount64();while(p.ready&&!p.quarantined&&p.phase!=Impl::Phase::Idle){std::string ignored;Poll(ignored);if(GetTickCount64()-start>=5000){p.quarantined=true;p.reason="Depth retirement timed out; GPU generation retained";break;}Sleep(1);}if(p.quarantined)return;if(p.backend&&p.module&&!p.module->Api()->close(p.backend)){p.quarantined=true;return;}p.backend=nullptr;p.ready=false;}
bool Dav2Host::Busy()const{return impl_->ready&&!impl_->quarantined&&(impl_->phase!=Impl::Phase::Idle||impl_->pending.has_value());}
bool Dav2Host::RequiresRestart()const{return impl_->quarantined;}bool Dav2Host::Ready()const{return impl_->ready&&!impl_->quarantined;}uint64_t Dav2Host::Fresh()const{return impl_->fresh.Count();}uint64_t Dav2Host::Dropped()const{return impl_->jobs.Dropped();}
